  let center = (world * vec4<f32>((boundsMin + boundsMax) * 0.5, 1.0)).xyz;
  let depth = length(center - view.cameraPosition);
  if (!lodFinite(radius) || radius <= 0.0 || !lodFinite(depth)) { return LOD_INVALID_HEIGHT; }
